import { userAPI } from './api';

describe('fetchUserById thunk', () => {
  let store;

  beforeEach(() => {
    // Reset all mocks before each test
    jest.clearAllMocks();
    // Create a test store
    store = createTestStore();
  });

  it('should fetch user successfully', async () => {
    const mockUser = { id: 'user-1', name: 'Alice', email: 'alice@example.com' };
    userAPI.getUser.mockResolvedValue({ data: mockUser });

    await store.dispatch(fetchUserById('user-1'));

    const state = store.getState();
    expect(state.users.entities['user-1']).toEqual(mockUser);
    expect(state.users.loading).toBe(false);
    expect(state.users.error).toBeNull();
  });

  it('should handle fetch error', async () => {
    userAPI.getUser.mockRejectedValue(new Error('User not found'));

    await store.dispatch(fetchUserById('invalid-id'));

    const state = store.getState();
    expect(state.users.loading).toBe(false);
    expect(state.users.error).toBe('User not found');
  });

  it('should set loading state while fetching', async () => {
    userAPI.getUser.mockImplementation(() => 
      new Promise(resolve => setTimeout(() => resolve({ data: {} }), 100))
    );

    const pendingAction = store.dispatch(fetchUserById('user-1'));

    // Check loading is true immediately after dispatch
    expect(store.getState().users.loading).toBe(true);

    await pendingAction;
    expect(store.getState().users.loading).toBe(false);
  });
});

